package org.marketreview.nativeapp;
import android.os.Handler;
import android.os.Looper;
import java.io.File;
import java.util.UUID;
import org.json.*;
final class PaperAutomationRuntime {
 interface Host{JSONObject snapshot()throws Exception;JSONObject preferences()throws Exception;String now();void refresh(JSONArray ids)throws Exception;}
 final PaperAutomationStore store;final String account;final Host host;private final Handler handler=new Handler(Looper.getMainLooper());
 private boolean active,busy;private long generation;private String status="";private AiKnowledgeRequest.Cancellation cancellation;
 Runnable changed;AiKnowledgeRequest.FakeConnection fake;
 private final Runnable timer=new Runnable(){public void run(){if(!active)return;try{tick();}catch(Exception e){status="等待 / 阻断："+e.getMessage();notifyChanged();}if(active)handler.postDelayed(this,30000);}};
 PaperAutomationRuntime(File file,String account,Host host){this.store=new PaperAutomationStore(file);this.account=account;this.host=host;}
 JSONObject book()throws Exception{return store.read(account);}String message(){return status;}boolean busy(){return busy;}
 private void notifyChanged(){if(changed!=null)changed.run();}
 private JSONObject mutate(PaperAutomationStore.Change change)throws Exception{JSONObject b=book();return store.transact(account,b.length()==0?-1:b.getLong("revision"),change,null);}
 void initialize(JSONObject settings)throws Exception{PaperAutomationModel.need(active,"paper-page-inactive");JSONObject snapshot=host.snapshot();mutate(b->{PaperAutomationModel.need(b.length()==0,"paper-book-already-exists");return PaperAutomationModel.seed(snapshot.getJSONObject("input"),settings,host.now());});status="纸面起始账本已建立，监控及模拟成交默认关闭。";notifyChanged();}
 void configure(JSONObject settings)throws Exception{PaperAutomationModel.need(active,"paper-page-inactive");JSONObject prior=book();PaperAutomationModel.need(prior.length()>0,"paper-book-not-initialized");JSONObject checked=PaperAutomationModel.configure(prior,settings,host.now());if(PaperMonitorModel.equal(checked,prior))return;++generation;if(cancellation!=null)cancellation.cancel();busy=false;mutate(b->PaperAutomationModel.configure(b,settings,host.now()));status="已保存本机纸面执行设置。";notifyChanged();}
 void prepare()throws Exception{PaperAutomationModel.need(active&&!busy,"paper-inactive-or-busy");JSONObject snapshot=host.snapshot();mutate(b->PaperAutomationModel.prepareTask(b,snapshot.getJSONObject("input"),host.now(),"manual:"+UUID.randomUUID()));status="分析材料已冻结，等待本次内容授权。";notifyChanged();}
 private String awaiting(JSONObject b)throws Exception{JSONObject tasks=b.getJSONObject("tasks");for(String id:PaperAutomationModel.keys(tasks))if(tasks.getJSONObject(id).getString("status").equals("awaiting-authorization"))return id;throw new IllegalArgumentException("没有等待授权的纸面分析任务");}
 AiKnowledgeRequest.Prepared request()throws Exception{PaperAutomationModel.need(active&&!busy,"paper-inactive-or-busy");JSONObject b=book(),t=b.getJSONObject("tasks").getJSONObject(awaiting(b));PaperAutomationModel.need(PaperAutomationModel.executionHash(b).equals(t.getString("executionHash")),"paper-material-changed");return AiKnowledgeRequest.preparePaper(host.preferences(),t.getJSONObject("prepared"));}
 void start(AiKnowledgeRequest.Prepared plan,AiKnowledgeRequest.Grant grant,AiKnowledgeRequest.Credential credential)throws Exception{
  PaperAutomationModel.need(active&&!busy,"paper-inactive-or-busy");AiKnowledgeRequest.Prepared expected=request();PaperAutomationModel.need(expected.digest().equals(plan.digest())&&java.util.Arrays.equals(expected.body(),plan.body()),"paper-request-changed");JSONObject before=book();String id=awaiting(before);JSONObject prepared=before.getJSONObject("tasks").getJSONObject(id).getJSONObject("prepared");PaperAutomationModel.executionInput(before,host.snapshot().getJSONObject("input"),host.now());
  mutate(b->PaperAutomationModel.claim(b,id,prepared.getString("preparationId"),host.now()));long owner=++generation;AiKnowledgeRequest.Cancellation token=new AiKnowledgeRequest.Cancellation();cancellation=token;busy=true;status="正在请求本次已授权分析。";notifyChanged();
  Thread worker=new Thread(()->{JSONObject result;try{result=AiKnowledgeRequest.execute(plan,grant,credential,token,fake);}catch(Exception e){try{result=new JSONObject().put("status","failed").put("errorCode",e.getMessage());}catch(Exception ignored){return;}}final JSONObject attempt=result;handler.post(()->{if(owner!=generation||!active)return;busy=false;try{
    String at=host.now();if(attempt.optString("status").equals("completed")){JSONObject source=host.snapshot().getJSONObject("input");mutate(b->{JSONObject next=PaperAutomationModel.accept(b,source,id,attempt.optString("report"),at,PaperAutomationModel.obj("source",attempt.get("provenance"),"attemptId",attempt.get("id"),"previewDigest",attempt.get("previewDigest"),"verification",attempt.get("verification")));next.getJSONObject("tasks").getJSONObject(id).put("requestAttempt",attempt);return next;});status="分析回包已保存并校验；成交仍须有效后续分钟行情。";}
    else{mutate(b->{JSONObject next=PaperAutomationModel.fail(b,id,at,attempt.optString("errorCode"),attempt.optString("status").equals("failed")||attempt.optString("status").equals("timed-out"));next.getJSONObject("tasks").getJSONObject(id).put("requestAttempt",attempt);return next;});status="本次请求未完成："+attempt.optString("status")+" / "+attempt.optString("errorCode");}
   }catch(Exception e){status="回包未消费："+e.getMessage();try{mutate(b->PaperAutomationModel.fail(b,id,host.now(),status,false));}catch(Exception ignored){status+="；状态写入冲突，重读后核对。";}}notifyChanged();});},"paper-authorized-analysis");worker.setDaemon(true);worker.start();
 }
 void tick()throws Exception{if(!active||busy)return;JSONObject b=book();if(b.length()==0||!b.getJSONObject("settings").getBoolean("enabled"))return;JSONObject snapshot=host.snapshot(),input=snapshot.getJSONObject("input");JSONArray ids=new JSONArray(PaperAutomationModel.keys(input.getJSONObject("quotes")));host.refresh(ids);String now=host.now();mutate(state->{JSONObject next=PaperAutomationModel.schedule(state,input,now),s=input.getJSONObject("session");if(s.getBoolean("verified")&&s.getBoolean("open")&&s.getBoolean("continuous"))next=PaperAutomationModel.execute(next,input,snapshot.getJSONObject("markets"),now);return next;});status="已核对当前交易日时段、分析任务及纸面订单；等待项保留原状态。";notifyChanged();}
 void cancel(String reason)throws Exception{++generation;if(cancellation!=null)cancellation.cancel();busy=false;if(book().length()>0)mutate(b->PaperAutomationModel.cancel(b,host.now(),reason));status="当前任务和未成交订单已取消。";notifyChanged();}
 void setActive(boolean value)throws Exception{if(active==value)return;active=value;handler.removeCallbacks(timer);if(active){handler.postDelayed(timer,30000);notifyChanged();}else cancel("page-left-or-backgrounded");}
}
